"""Zero-JS, fully inline mobile-friendly investor-grade research snapshot."""
import csv, html, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
out=ROOT/'dashboard/ProfitLeak_Atlas_Expert_iPhone.html'
metrics=json.loads((ROOT/'data/marts/metrics.json').read_text())
risk=json.loads((ROOT/'data/marts/risk_model_validation.json').read_text())
challenge=json.loads((ROOT/'data/marts/challenge_validation.json').read_text())
settlement=json.loads((ROOT/'data/marts/settlement_validation.json').read_text())
workflow=json.loads((ROOT/'data/marts/workflow_status.json').read_text())
def get(fname):
 with (ROOT/'data/marts'/fname).open(newline='',encoding='utf8') as f:return list(csv.DictReader(f))
months=get('monthly.csv'); causes=get('root_causes.csv');audit=get('audit_casebook.csv'); vendors=get('vendors.csv')
def eur(x,short=False):
 x=float(x)
 if short and x>=1e6:return f'€{x/1e6:,.2f}M'
 if short and x>=1e3:return f'€{x/1e3:,.1f}K'
 return f'€{x:,.0f}'
def pct(x):return f'{float(x)*100:.1f}%'
def esc(s):return html.escape(str(s))
# Smooth polylines embedded in SVG; no script or external assets needed.
values=[float(m['gross_loss_eur']) for m in months]
recovery=[float(m['modeled_recovery_eur']) for m in months]
maxv=max(max(values, default=0)*1.18, 1)
x0,y0,w,h=55,22,840,190
point=lambda i,n,v: (x0+w*i/max(n-1,1),y0+h*(1-v/maxv))
series1=[point(i,len(values),v) for i,v in enumerate(values)]
series2=[point(i,len(values),v) for i,v in enumerate(recovery)]
coords=lambda pts:' '.join(f'{x:.1f},{y:.1f}' for x,y in pts)
area=f'{x0},{y0+h} '+coords(series1)+f' {x0+w},{y0+h}'
monthslabels=''.join(f'<text x="{x0+w*i/max(len(values)-1,1):.1f}" y="244" text-anchor="middle" font-size="13" fill="#93a6c1">{esc(m["payment_month"][2:])}</text>' for i,m in enumerate(months) if i%4==0 or i==len(months)-1)
grid=''.join(f'<line x1="{x0}" x2="{x0+w}" y1="{y0+h*(1-j/4):.1f}" y2="{y0+h*(1-j/4):.1f}" stroke="#233349" stroke-width="1"/>' for j in range(5))
trend=f'<svg viewBox="0 0 930 264" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Gross potential leakage and recoverable trend over 22 months">{grid}<polygon points="{area}" fill="#F3BC73" fill-opacity="0.09"/><polyline points="{coords(series1)}" fill="none" stroke="#F3BC73" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><polyline points="{coords(series2)}" fill="none" stroke="#53D8C0" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>{monthslabels}</svg>'
maxcause=max(max((float(c['gross_loss_eur']) for c in causes), default=0), 1)
causebars=''.join(f'''<div class="bar-row"><div class="bar-head"><strong>{esc(c['issue_type'])}</strong><span>{eur(c['gross_loss_eur'],True)}</span></div><div class="bar-rail"><div style="width:{float(c['gross_loss_eur'])/maxcause*100:.1f}%;background:{'#F3BC73' if c['issue_type']!='Approval fragmentation' else '#71829A'}"></div></div></div>''' for c in causes)
topvendors=''.join(f'<tr><td>{esc(v["vendor_name"])}</td><td>{esc(v["category"])}</td><td class="num">{eur(v["gross_loss_eur"],True)}</td></tr>' for v in vendors[:8])
topcases=''.join(f'<tr><td class="mono">{esc(c["payment_id"])}</td><td>{esc(c["issue_type"])}</td><td class="num">{eur(c["financial_exposure_eur"])}</td><td><span class="status">{esc(c["status"])}</span></td></tr>' for c in audit[:8])
psir=''.join(f'<tr><td>{esc(k)}</td><td class="num">{float(v):.3f}</td></tr>' for k,v in sorted(risk['category_psi'].items(),key=lambda kv:-kv[1]))
html_text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark"><title>ProfitLeak Atlas • Expert Edition</title><style>
:root{{--bg:#071321;--panel:#11233a;--line:#263d56;--text:#f1f6fc;--muted:#93a6c1;--mint:#53d8c0;--orange:#f3bc73;--pink:#ed7190}}*{{box-sizing:border-box}}html{{background:var(--bg)}}body{{margin:0;background:radial-gradient(ellipse at 84% 0,#163951 0,transparent 43%),var(--bg);font:15px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;color:var(--text)}}main{{max-width:1260px;margin:auto;padding:35px 30px 80px}}.small{{font-size:12px;letter-spacing:2.3px;font-weight:800;text-transform:uppercase;color:var(--mint)}}.brand{{display:flex;align-items:center;gap:12px;margin-bottom:25px}}.mark{{font-size:26px;font-weight:900;border:1px solid #4ca7a1;border-radius:13px;display:inline-grid;place-items:center;width:46px;height:46px;color:var(--mint)}}h1{{font-size:clamp(34px,4vw,67px);line-height:1.06;letter-spacing:-2px;margin:8px 0 18px;max-width:800px}}h1 em{{font-style:normal;color:var(--mint)}}h2{{font-size:21px;letter-spacing:-.5px;margin:0 0 15px}}.hero p{{max-width:790px;color:var(--muted);font-size:16px}}.stamp{{display:inline-flex;border:1px solid #436b75;background:#10303a;padding:7px 12px;border-radius:50px;color:#c4ede6;font-size:12px;font-weight:700;margin-top:6px}}.grid{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:36px 0 28px}}.kpi,.panel{{border:1px solid var(--line);background:linear-gradient(145deg,#172c46,#0e1d31);border-radius:20px;padding:25px;box-shadow:0 15px 35px #030a1233}}.kpi{{min-height:152px;position:relative;overflow:hidden}}.kpi:before{{content:'';height:4px;background:var(--mint);position:absolute;left:24px;right:63%;top:0}}.kpi.amber:before{{background:var(--orange)}}.kpi.pink:before{{background:var(--pink)}}.kpi .name{{font-size:11px;letter-spacing:1.6px;color:var(--muted);font-weight:800;text-transform:uppercase}}.kpi .val{{font-size:clamp(27px,3vw,38px);font-weight:800;letter-spacing:-1.5px;margin-top:15px}}.kpi .sub{{color:var(--muted);font-size:12px;margin-top:1px}}.cols{{display:grid;grid-template-columns:1.35fr 1fr;gap:18px;margin:18px 0}}.panel{{padding:26px}}.sub{{color:var(--muted);font-size:13px}}.legend{{display:flex;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:12px}}.dot{{display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--orange);margin-right:6px}}.dot.mint{{background:var(--mint)}}.chart{{margin-top:20px}}svg{{width:100%;height:auto;display:block}}.bar-row{{margin:17px 0}}.bar-head{{display:flex;justify-content:space-between;font-size:12px;gap:10px}}.bar-head strong{{font-size:12px;font-weight:650}}.bar-head span{{color:var(--orange);font-weight:800}}.bar-rail{{height:9px;background:#263a52;border-radius:50px;overflow:hidden;margin-top:7px}}.bar-rail>div{{height:100%;border-radius:50px}}.challenge{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:18px}}.challenge>div{{border-radius:13px;padding:16px;background:#0d2035;border:1px solid #274159}}.challenge .big{{font-size:29px;font-weight:850;color:var(--mint)}}.challenge label{{font-size:11px;letter-spacing:.7px;color:var(--muted);display:block}}.riskbad{{color:var(--orange)!important}}table{{width:100%;border-collapse:collapse;font-size:12px}}td,th{{border-bottom:1px solid #263a51;padding:11px 8px;vertical-align:top;text-align:left}}th{{color:var(--muted);text-transform:uppercase;letter-spacing:.6px;font-size:10px}}.num{{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}}.mono{{font-family:ui-monospace,monospace}}.status{{color:#90d5d4;background:#193844;border:1px solid #2d7173;border-radius:16px;padding:3px 8px;white-space:nowrap}}.nav{{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}}.nav a{{display:inline-block;color:#b6f2e8;border:1px solid #3d6572;padding:7px 12px;border-radius:8px;text-decoration:none}}.nav a:focus-visible{{outline:2px solid var(--mint);outline-offset:3px}}.foot{{border-top:1px solid var(--line);padding-top:22px;margin-top:35px;color:var(--muted);font-size:12px}}.pill{{display:inline-block;padding:4px 10px;background:#263a54;border-radius:12px;font-size:11px;color:#b8d1e3;margin-right:8px}}@media(max-width:920px){{.grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}.cols{{grid-template-columns:1fr}}}}@media(max-width:570px){{main{{padding:21px 15px 55px}}.grid{{gap:9px;margin:24px 0 17px}}.kpi,.panel{{padding:17px;border-radius:16px}}.kpi{{min-height:125px}}.kpi .val{{font-size:25px}}.kpi .name{{letter-spacing:.7px;font-size:10px}}.panel{{padding:19px}}h1{{font-size:36px;letter-spacing:-1.3px}}h2{{font-size:19px}}.challenge{{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}}.challenge>div{{padding:10px}}.challenge .big{{font-size:19px}}.challenge label{{font-size:9px}}table{{font-size:10px}}td,th{{padding:8px 4px}}.brand{{margin-bottom:18px}}}}
</style></head><body><main>
<div class="brand"><div class="mark">◈</div><div><div style="font-weight:750;font-size:14px">PROFITLEAK / ATLAS</div></div></div>
<header class="hero"><h1>Procurement payment <em>forensics</em></h1><p>Investigate spend exceptions, verify invoice settlements and prioritize cases for audit review.</p><div class="stamp">Synthetic case study · €0 real-world recovery</div><nav class="nav" aria-label="Project demos"><a href="__EXPLORE__">Explore cases and recovery scenarios</a><a href="__PUBLIC__">Public-data quality pilot</a></nav></header>
<section class="grid"><div class="kpi"><div class="name">Payments screened</div><div class="val">{metrics['payments']:,}</div><div class="sub">Across 22 simulated months</div></div><div class="kpi amber"><div class="name">Procurement spend</div><div class="val">{eur(metrics['spend_eur'],True)}</div><div class="sub">Fictional EU organization</div></div><div class="kpi pink"><div class="name">Potential exposure</div><div class="val">{eur(metrics['gross_estimated_loss_eur'],True)}</div><div class="sub">Unconfirmed audit opportunity</div></div><div class="kpi"><div class="name">Modeled recovery</div><div class="val">{eur(metrics['modeled_recoverable_eur'],True)}</div><div class="sub">Scenario — actual recovery €0</div></div></section>
<section class="cols"><div class="panel"><div class="small">01 / Exposure velocity</div><h2>Financial leakage trajectory</h2><p class="sub">Potential exposure and modeled recovery by month, EUR</p><div class="legend"><span><i class="dot"></i> Gross exposure</span><span><i class="dot mint"></i> Modelled recovery</span></div><div class="chart">{trend}</div></div><div class="panel"><div class="small">02 / Root causes</div><h2>Exposure by exception type</h2><p class="sub">Financial estimates and control exceptions with zero assigned exposure</p>{causebars}</div></section>
<section class="cols"><div class="panel"><div class="small">03 / Model governance</div><h2>Payment-size screening</h2><p class="sub">Synthetic challenge of 1,500 payments, including legitimate large orders and subtle anomalies. These figures measure the amount-only screen.</p><div class="challenge"><div><label>Precision</label><div class="big riskbad">{pct(challenge['precision'])}</div></div><div><label>Recall</label><div class="big riskbad">{pct(challenge['recall'])}</div></div><div><label>False alarms</label><div class="big">{challenge['false_positive']}</div></div></div><p class="sub" style="margin-top:20px">The model misses subtle patterns and can flag legitimate large payments. Every alert requires independent evidence review.</p><div class="small" style="margin-top:23px">Historical-to-holdout shift (PSI)</div><table><thead><tr><th>Category</th><th class="num">PSI</th></tr></thead><tbody>{psir}</tbody></table></div>
<div class="panel"><div class="small">Case review</div><h2>Evidence-led investigation queue</h2><p class="sub">{len(audit)} seeded simulated cases with status transitions, ownership, evidence references and append-only activity history in the SQLite case workflow.</p><div class="challenge"><div><label>Cases opened</label><div class="big">{len(audit)}</div></div><div><label>Review status</label><div class="big">{workflow['status_counts'].get('New',0):,} new</div></div><div><label>Cash realized</label><div class="big">{eur(workflow['actual_cash_recovered_in_synthetic_demonstration_eur'])}</div></div></div><div style="overflow-x:auto;margin-top:25px"><table><thead><tr><th>ID</th><th>Rule signal</th><th class="num">Exposure</th><th>Status</th></tr></thead><tbody>{topcases}</tbody></table></div></div></section>
<section class="panel"><h2>Invoice settlement validation</h2><p class="sub">{settlement['settlements']:,} separately simulated settlements with installments, excess payments and incomplete authorizations.</p><div class="challenge"><div><label>Legacy false flags</label><div class="big">{settlement['repeat_only_baseline']['fp']:,}</div></div><div><label>Revised false flags</label><div class="big">{settlement['authorization_aware_rule']['fp']:,}</div></div><div><label>Manual reviews</label><div class="big">{settlement['ambiguous_follow_up_reviews']:,}</div></div></div><p class="sub">Ambiguous authorizations enter manual review with zero assigned exposure. Results apply to the designed scenarios.</p></section>
<section class="panel" style="margin-top:18px"><div class="small">Supplier concentration</div><h2>Where analysts should start</h2><p class="sub">Top suppliers ranked by modeled gross potential exposure, not established wrongdoing</p><div style="overflow-x:auto"><table><thead><tr><th>Supplier</th><th>Category</th><th class="num">Risk exposure</th></tr></thead><tbody>{topvendors}</tbody></table></div></section>
<footer class="foot"><span class="pill">Python</span><span class="pill">SQL / SQLite</span><span class="pill">Excel</span><span class="pill">Power BI PBIP</span><p>All names, companies, payment records, benchmark labels and money figures are synthetic. Estimates and scoring do not establish fraud, debt, credit recoverability or real savings. Power BI source is not validated in Windows Desktop.</p><p>© Portfolio case study · ProfitLeak Atlas Expert Edition · Offline iPhone-compatible HTML. No JavaScript, third-party libraries, remote fonts or external images.</p></footer></main></body></html>'''
out.write_text(html_text.replace('__EXPLORE__','atlas_executive.html').replace('__PUBLIC__','Public_Data_Validation_iPhone.html'),encoding='utf8')
(ROOT/'docs/index.html').write_text(html_text.replace('__EXPLORE__','explore.html').replace('__PUBLIC__','public-data.html'),encoding='utf8')
print('Static dashboard',out,round(out.stat().st_size/1024,1),'KB')
